        "ghf-001": {"prompt":"¿Qué información conserva el control de versiones sobre un proyecto?","choices":["Los cambios y su historial","Solo el contenido más reciente","Solo el nombre de la rama actual","Los archivos y su salida de ejecución"],"explanations":["El control de versiones registra cambios a lo largo del tiempo.","Guardar solo la copia más reciente pierde revisiones anteriores.","Los nombres de ramas no describen por sí solos los cambios.","La salida de ejecución no se registra automáticamente."],"concept":"El control de versiones permite inspeccionar estados anteriores y la evolución del proyecto.","hints":["Distingue los archivos que editas del historial guardado del proyecto.","Considera si la operación registra, inspecciona o combina trabajo."]},
        "ghf-002": {"prompt":"¿Qué pareja identifica correctamente Git y GitHub?","choices":["Registro de paquetes; editor de código","Sistema de control de versiones; plataforma colaborativa","Plataforma colaborativa; sistema de control de versiones","Editor de código; registro de paquetes"],"explanations":["Git no es un registro de paquetes.","Git versiona archivos; GitHub aloja colaboración basada en Git.","Esta opción invierte las funciones de ambos productos.","Git no es un editor de código."],"concept":"Git funciona de forma independiente; GitHub añade colaboración alojada sobre repositorios.","hints":["Relaciona la interfaz con el lugar donde se realiza la tarea.","Distingue las operaciones de Git de las funciones colaborativas de GitHub."]},
        "ghf-003": {"prompt":"¿Qué comando crea un repositorio Git local a partir de uno remoto existente?","choices":["git fetch https://github.com/octo-org/handbook.git","git pull https://github.com/octo-org/handbook.git","git clone https://github.com/octo-org/handbook.git","git init https://github.com/octo-org/handbook.git"],"explanations":["Fetch obtiene objetos en un repositorio local existente.","Pull opera dentro de un repositorio local existente.","Clone crea un repositorio local con el historial remoto.","Init inicializa un repositorio, no copia el historial remoto."],"concept":"Clonar crea el repositorio local y configura su remoto inicial.","hints":["Distingue el historial local del historial de otro repositorio.","Comprueba si se necesita descargar, integrar o subir cambios."]},
