        "ghf-005": {"prompt":"¿Qué registra un commit de Git?","choices":["Una instantánea del proyecto y metadatos","Una copia activa de toda edición futura","Un despliegue y sus registros de ejecución","Una URL remota y sus credenciales"],"explanations":["Un commit registra una instantánea, mensaje, autoría y metadatos relacionados.","Las ediciones posteriores necesitan otro commit.","Un commit no despliega ni recopila registros por sí mismo.","La configuración remota es independiente de las instantáneas."],"concept":"Los commits representan estados guardados, no las ediciones continuas del directorio de trabajo.","hints":["Distingue los archivos que editas del historial guardado del proyecto.","Considera si la operación registra, inspecciona o combina trabajo."]},
        "ghf-006": {"prompt":"En GitHub flow, ¿por qué se crea una rama antes de editar?","choices":["Para sustituir el repositorio remoto","Para aislar los cambios propuestos","Para conceder permisos al repositorio","Para publicar una versión de inmediato"],"explanations":["Una rama forma parte del historial de su repositorio.","Una rama separa el trabajo en curso de la rama predeterminada.","Crear una rama no concede acceso.","Crear una rama no crea una versión publicada."],"concept":"Las ramas permiten aislar cambios para revisarlos antes de integrarlos.","hints":["Piensa en las etapas de una contribución basada en ramas.","Distingue proponer un cambio de incorporarlo a otra rama."]},
        "ghf-007": {"prompt":"¿Qué operación de Git envía commits de una rama local a un remoto?","choices":["git merge","git add","git push","git fetch"],"explanations":["Merge integra historiales localmente.","Add prepara contenido de archivos locales.","Push actualiza el remoto con commits locales.","Fetch descarga objetos y referencias remotos."],"concept":"Un commit local se comparte con un remoto mediante push.","hints":["Distingue el historial local del historial de otro repositorio.","Comprueba si se necesita descargar, integrar o subir cambios."]},
        "ghf-008": {"prompt":"¿Qué comando actualiza referencias de seguimiento remoto sin integrarlas en la rama actual?","choices":["git pull origin main","git merge origin/main","git push origin main","git fetch origin"],"explanations":["Pull también intenta integrar los cambios obtenidos.","Merge integra un historial ya disponible.","Push envía commits locales, no obtiene actualizaciones.","Fetch obtiene actualizaciones remotas sin fusionarlas."],"concept":"Obtener cambios e integrarlos son pasos distintos.","hints":["Distingue el historial local del historial de otro repositorio.","Comprueba si se necesita descargar, integrar o subir cambios."]},
        "ghf-009": {"prompt":"Con pull configurado para fusionar, ¿qué hace git pull?","choices":["Obtiene cambios y después los fusiona","Prepara cambios y después los confirma","Confirma cambios y después los sube","Crea una rama y después cambia a ella"],"explanations":["Pull basado en merge combina obtener y fusionar cambios.","Pull no prepara ni confirma ediciones del directorio de trabajo.","Pull obtiene actualizaciones en lugar de publicar commits.","Crear ramas no es la operación que define pull."],"concept":"Pull integra trabajo obtenido; su estrategia de integración se puede configurar.","hints":["Distingue el historial local del historial de otro repositorio.","Comprueba si se necesita descargar, integrar o subir cambios."]},
        "ghf-010": {"prompt":"Git no puede combinar automáticamente ediciones incompatibles de las mismas líneas. ¿Cómo se llama esto?","choices":["Una fusión de avance rápido","Un conflicto de fusión","Un HEAD separado","Un clon superficial"],"explanations":["Un avance rápido mueve una referencia sin historiales divergentes.","Los cambios incompatibles requieren resolver el contenido deseado.","HEAD separado describe la posición de checkout, no ediciones incompatibles.","Un clon superficial limita el historial descargado."],"concept":"Los conflictos de fusión requieren resolver el contenido antes de completar la integración.","hints":["Piensa en las etapas de una contribución basada en ramas.","Distingue proponer un cambio de incorporarlo a otra rama."]},
        "ghf-011": {"prompt":"¿Qué operación deshace un commit publicado añadiendo un nuevo commit inverso?","choices":["Rebase","Amend","Revert","Reset"],"explanations":["Rebase vuelve a aplicar commits sobre otra base.","Amend sustituye el commit más reciente.","Revert registra un commit que invierte un cambio anterior.","Reset mueve una referencia en lugar de añadir un commit inverso."],"concept":"Revertir conserva el historial compartido existente y añade un cambio que deshace otro.","hints":["Piensa en las etapas de una contribución basada en ramas.","Distingue proponer un cambio de incorporarlo a otra rama."]},
        "ghf-012": {"prompt":"¿Qué comando registra los cambios ya preparados con un mensaje?","choices":["git add -m \"Correct setup instructions\"","git push -m \"Correct setup instructions\"","git status -m \"Correct setup instructions\"","git commit -m \"Correct setup instructions\""],"explanations":["Add prepara contenido; esta no es su sintaxis de mensajes.","Push transfiere commits, no crea este commit.","Status informa del estado, no crea commits.","Commit registra el contenido preparado y el mensaje indicado."],"concept":"Preparar selecciona contenido; confirmar lo registra con un mensaje.","hints":["Distingue los archivos que editas del historial guardado del proyecto.","Considera si la operación registra, inspecciona o combina trabajo."]},
        "ghf-013": {"prompt":"¿Qué comando muestra los remotos de Git configurados y sus URL de fetch y push?","choices":["git remote -v","git branch -v","git status -s","git log --oneline"],"explanations":["Remote con -v muestra los nombres y URL de los remotos.","Branch enumera ramas e información de commits.","Status resume cambios del directorio de trabajo y del índice.","Log muestra el historial de commits registrado."],"concept":"La configuración de remotos asocia nombres con URL de conexión a repositorios.","hints":["Distingue el historial local del historial de otro repositorio.","Comprueba si se necesita descargar, integrar o subir cambios."]},
        "ghf-014": {"prompt":"¿Qué secuencia sigue el flujo principal de GitHub flow?","choices":["Commit -> fusión -> rama -> pull request","Rama -> commit -> pull request -> fusión","Pull request -> fusión -> rama -> commit","Fusión -> commit -> pull request -> rama"],"explanations":["La rama de trabajo se crea antes de proponer sus cambios.","El trabajo se aísla, registra, propone y después se integra.","Una propuesta necesita una rama con cambios antes de fusionarse.","La fusión no precede ni al trabajo ni a su propuesta."],"concept":"GitHub flow organiza el trabajo en ramas mediante revisión de pull requests.","hints":["Piensa en las etapas de una contribución basada en ramas.","Distingue proponer un cambio de incorporarlo a otra rama."]},
        "ghf-015": {"prompt":"¿Qué ocurre al subir otro commit a la rama de origen de un pull request abierto?","choices":["El pull request se fusiona automáticamente","La rama base avanza hasta ese commit","El pull request incluye ese commit","Se abre otro pull request automáticamente"],"explanations":["Los commits nuevos no autorizan por sí mismos la fusión.","La rama base cambia mediante una actualización o fusión independiente.","La propuesta sigue las actualizaciones de su rama de origen.","Subir cambios no abre automáticamente otra propuesta."],"concept":"Un pull request abierto refleja el contenido actual de su rama de origen.","hints":["Piensa en las etapas de una contribución basada en ramas.","Distingue proponer un cambio de incorporarlo a otra rama."]},
