        "ghf-019": {"prompt":"¿Qué comando identifica archivos preparados, modificados sin preparar y sin seguimiento?","choices":["git branch","git remote","git status","git log"],"explanations":["Branch enumera o gestiona referencias de ramas.","Remote gestiona alias de conexión a repositorios.","Status informa del directorio de trabajo y del área de preparación.","Log muestra commits, no el estado actual de los archivos."],"concept":"Status distingue los cambios actuales del historial de commits registrado.","hints":["Distingue los archivos que editas del historial guardado del proyecto.","Considera si la operación registra, inspecciona o combina trabajo."]},
