        "ghf-021": {"prompt":"¿Qué comando inicializa los metadatos de Git en la carpeta actual?","choices":["git init","git clone","git add","git commit"],"explanations":["Init crea metadatos del repositorio en el directorio actual.","Clone copia un repositorio existente a uno local.","Add requiere un repositorio y prepara contenido.","Commit registra contenido preparado en un repositorio existente."],"concept":"Inicializar crea un repositorio; preparar y confirmar son operaciones distintas.","hints":["Distingue los archivos que editas del historial guardado del proyecto.","Considera si la operación registra, inspecciona o combina trabajo."]},
        "ghf-022": {"prompt":"En un repositorio Git no bare, ¿qué es el directorio de trabajo?","choices":["Los metadatos de una versión firmada","Los archivos extraídos disponibles para editar","El contenido seleccionado para el próximo commit","El conjunto completo de ramas remotas"],"explanations":["Los metadatos de firma no definen el directorio de trabajo.","El directorio de trabajo contiene los archivos actualmente extraídos.","El contenido seleccionado se almacena en el índice.","Las ramas remotas son referencias, no archivos de trabajo."],"concept":"El directorio de trabajo, el índice y el historial de commits son conceptos distintos.","hints":["Distingue los archivos que editas del historial guardado del proyecto.","Considera si la operación registra, inspecciona o combina trabajo."]},
